import React, { useState } from "react";
import Login from "./components/Login";
import Dashboard from "./components/Dashboard";

import IncomeCategory from "./components/IncomeCategory";
import Questionnaire from "./components/Questionnaire";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";
import Preview from "./components/Preview";

function App() {

  const [user, setUser] = useState(null);
  const [step, setStep] = useState("login");

  // ✅ LOGIN
  const handleLogin = (userData) => {
    setUser(userData);

    const existing = localStorage.getItem(`userData_${userData.email}`);

    if (existing) {
      setStep("dashboard");
    } else {
      setStep("income");
    }
  };

  // ✅ COMPLETE FLOW
  const handleComplete = () => {
    if (user) {
      localStorage.setItem(`userData_${user.email}`, "true");
    }
    setStep("dashboard"); // ✅ FIX
  };

  // ✅ LOGOUT
  const handleLogout = () => {
    localStorage.removeItem("user");
    setUser(null);
    setStep("login");
  };

  // ================= FLOW =================

  if (step === "login") {
    return <Login onLogin={handleLogin} />;
  }

  if (step === "income") {
    return (
      <IncomeCategory
        onNext={() => setStep("questionnaire")}
      />
    );
  }

  if (step === "questionnaire") {
    return (
      <Questionnaire
        onNext={() => setStep("priority")}
        onBack={() => setStep("income")}
      />
    );
  }

  if (step === "priority") {
    return (
      <SpendingPriority
        onNext={() => setStep("budget")}
        onBack={() => setStep("questionnaire")}
      />
    );
  }

  if (step === "budget") {
    return (
      <BudgetLimits
        onNext={() => setStep("preview")}
        onBack={() => setStep("priority")}
      />
    );
  }

  if (step === "preview") {
    return (
      <Preview
        onConfirm={handleComplete}   // ✅ FIX
        onBack={() => setStep("budget")} // ✅ FIX
      />
    );
  }

  if (step === "dashboard") {
    return (
      <Dashboard
        user={user}
        onLogout={handleLogout}
      />
    );
  }

  return null;
}

export default App;
